import boto3

def extract_receipt_fields(receipt_image):
    textract_client = boto3.client('textract')
    response = textract_client.analyze_document(
        Document={'Bytes': receipt_image},
        FeatureTypes=['TABLES', 'FORMS']
    )
    merchant = None
    tax = None
    total = None
    items = []
    for block in response['Blocks']:
        if block['BlockType'] == 'KEY_VALUE_SET':
            if block['Text'] == 'Merchant':
                merchant = block['ValueDetection']['Text']
            elif block['Text'] == 'Tax':
                tax = block['ValueDetection']['Text']
            elif block['Text'] == 'Total':
                total = block['ValueDetection']['Text']
        elif block['BlockType'] == 'TABLE':
            for relationship in block['Relationships']:
                if relationship['Type'] == 'CHILD':
                    for child_id in relationship['Ids']:
                        for child_block in response['Blocks']:
                            if child_block['Id'] == child_id:
                                if child_block['BlockType'] == 'CELL':
                                    items.append(child_block['Text'])
    return {'merchant': merchant, 'tax': tax, 'total': total, 'items': items}

def normalize_expense(extracted_fields):
    normalized_expense = {
        'vendor': extracted_fields.get('vendor', ''),
        'date': extracted_fields.get('date', ''),
        'total': extracted_fields.get('total', ''),
        'line_items': extracted_fields.get('line_items', [])
    }
    return normalized_expense

import boto3

def validate_document_fields(extracted_fields):
    required_fields = ['vendor', 'date', 'total']
    for field in required_fields:
        if field not in extracted_fields or not extracted_fields[field]:
            return False
    return True

